export const deleteStudent = async (studentId) => {
  const token = localStorage.getItem("token");

  return fetch(`/api/studentprofile/${studentId}`, {
    method: "DELETE",
    headers: {
      Authorization: `Bearer ${token}`,
    },
  });
};
